#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/python/tasks/code-lint-uv.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Fail when a uv.lock does not agree with its pyproject.toml"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="lint every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="accepted for the code:lint contract"
# USAGE flag "--fix" help="accepted for the code:lint contract; run mise run setup:deps:50-python --upgrade to write the lockfile"
# USAGE arg "[files]" var=#true help="the files to lint; only a pyproject.toml or a uv.lock selects its project; the default is the uncommitted files"
# FILES include="pyproject.toml uv.lock"

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Shipped with the python tool. Without uv, the task does not apply and prints
# nothing.
if not helpers.has_tool("uv"):
  sys.exit(0)
os.chdir(os.environ["MISE_PROJECT_ROOT"])

# code:lint passes its flags and files to each code:lint:* task. The list
# comes from gate_files (the # FILES header above). An empty list: nothing
# to do.
args = [f"--{flag}" for flag in ("all", "debug", "fix") if os.environ.get(f"usage_{flag}") == "true"]
listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
try:
  if os.path.getsize(listing) == 0:
    sys.exit(0)

  # A pyproject.toml or a uv.lock of the list selects its project, when the
  # project has both files. No project: nothing to do.
  with open(listing, encoding="utf-8", errors="surrogateescape") as f:
    files = f.read().split("\n")[:-1]
  projects = []
  for file in files:
    folder = os.path.dirname(file) or "."
    if not (os.path.isfile(f"{folder}/uv.lock") and os.path.isfile(f"{folder}/pyproject.toml")):
      continue
    if folder not in projects:
      projects.append(folder)
  if not projects:
    sys.exit(0)

  helpers.print_header("Checking the uv lockfiles ...")
  for folder in projects:
    helpers.print_subheader(f"Checking {folder}/uv.lock ...")
    result = helpers.tool("uv", "lock", "--check", "--directory", folder)
    if result.returncode != 0:
      sys.exit(result.returncode)
finally:
  os.remove(listing)
